#' Read a VCF object from disk
#'
#' Read a \link[VariantAnnotation]{VCF} object from its on-disk representation.
#'
#' @param path String containing a path to a directory, usually generated by the \code{\link[alabaster.base]{saveObject}} method for \link[VariantAnnotation]{VCF} objects.
#' @param metadata Named list of metadata for this object, see \code{\link[alabaster.base]{readObjectFile}} for details.
#' @param ... Further arguments passed to internal \code{\link[alabaster.base]{altReadObject}} calls.
#'
#' @return A \link[VariantAnnotation]{VCF} object. 
#'
#' @seealso
#' \code{\link{saveObject,VCF-method}}, to save VCF objects to disk.
#'
#' @author Aaron Lun
#'
#' @examples
#' fl <- system.file("extdata", "structural.vcf", package="VariantAnnotation")
#' vcf <- readVcf(fl)
#'
#' tmp <- tempfile()
#' saveObject(vcf, tmp)
#' readObject(tmp)
#' 
#' @export
#' @aliases
#' loadVCF
#' loadVCFHeader
#' @import alabaster.base VariantAnnotation
readVCF <- function(path, metadata, ...) {
    # Note that this doesn't work with regular Gzipped files right now, only
    # BGZF-compressed files, see Bioconductor/VariantAnnotation#32.
    out <- readVcf(file.path(path, "file.vcf.gz"))
    if (isTRUE(metadata$vcf_experiment$expanded)) {
        out <- expand(out)
    }
    out
}

